// TH15 v1.00b Stage 4 道中 MainSub06 (st04.ecl.txt:1293-1332)
// 依赖 ECir06 (509-543) 与 ECir06_at (545-595)。
// 卡帧0 = 源行1293进入；开场缓冲后按源等待走四轮三对编队。

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 10, 6)：type10 -> TH15_SHARD，color 6。
const TH15_SHARD: int = 512;

// ECir06_at：wait(10) 后配置发射器，再按 rank 打 volleys 轮。
// 每轮：fixed ring，5 颗整周均分，基角 = ANGLE_PLAYER + RANDF2*spread。
async sub ecir06_shots() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1.5fx;   // etSpeed([-1.0f], 0.2)：单层只取首速
    var gap: int = 10;       // wait([-1])
    var volleys: int = 40;   // diffI($B, 40, 90, 110, 120)
    var spread: int = 182;   // RANDF2 幅度 0.017453292 rad
    if rank == RANK_NORMAL {
        speed = 2.5fx; gap = 5; volleys = 90; spread = 1274;
    } else if rank == RANK_HARD {
        speed = 3.5fx; gap = 4; volleys = 110; spread = 1820;
    } else if rank == RANK_LUNATIC {
        speed = 4fx; gap = 4; volleys = 120; spread = 1820;
    }
    sh_reset(0);
    sh_sprite(0, TH15_SHARD, 6);
    sh_ring(0, 1);       // etAim(0,3)：固定方向整周环
    sh_aim(0, 0);
    sh_count(0, 5, 1);   // etCount(0,5,1)
    sh_speed(0, speed, 0fx);
    sh_dist(0, 32fx - 4fx * speed);  // etDist(32) 与 ANIM 出生退位移 -4*初速 合成
    for i in 0..volleys {
        sh_angle(0, (aim_player() as int + (rand(2 * spread + 1) - spread)) as angle, 0deg);
        sh_fire(0);
        wait(gap);
    }
}

// ECir06：出生上升到创建点，120帧后放开体碰并启动发弹；再180帧朝自机加速。
async sub ecir06(px: fx, py: fx) {
    set_invuln(65535);
    set_hitbox(8fx);    // setHitbox(16,16)：普通圆分支 16*0.5
    set_hurtbox(12fx);  // setHurtbox(24,24)：24*0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);  // flagSet(15) 中的体碰关闭位
    move_to(120, px, py, EASE_QUAD_IN);  // movePosRel(0,32)+movePosRelTime(120,1,0,0)
    wait(120);
    set_enemy_flag(ENEMY_NO_BODY, 0);    // flagClear(15)
    spawn ecir06_shots();
    wait(180);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);  // moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 1fx, EASE_LINEAR);            // moveSpeedTime(120, 0, 1.0)
    loop { wait(1000); }
}

// 一组左右对称的两只；源出生点下方32px起，交给 ecir06 升到创建坐标。
sub wave_pair(ax: fx, ay: fx) {
    _ = spawn_enemy(-ax, ay + 32fx, 550, 0, 1000, 0, ecir06(-ax, ay));
    _ = spawn_enemy(ax, ay + 32fx, 550, 0, 1000, 0, ecir06(ax, ay));
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave_pair(128fx, 128fx);
    wait(40);
    wave_pair(160fx, 192fx);
    wait(40);
    wave_pair(64fx, 96fx);
    wait(400);
    wave_pair(128fx, 128fx);
    wait(40);
    wave_pair(160fx, 192fx);
    wait(40);
    wave_pair(64fx, 96fx);
    wait(400);
    wave_pair(128fx, 128fx);
    wait(40);
    wave_pair(160fx, 192fx);
    wait(40);
    wave_pair(64fx, 96fx);
    wait(300);
    wave_pair(128fx, 128fx);
    wait(40);
    wave_pair(160fx, 192fx);
    wait(40);
    wave_pair(64fx, 96fx);
    wait(400);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
